#!/usr/bin/env python3
import json
from pathlib import Path

PATH=Path(__file__).resolve().parents[1]/"App/Resources/history.json"
d=json.loads(PATH.read_text())

sources=[
("v205_ss88","《宋书》卷八十八·薛安都等传","https://zh.wikisource.org/wiki/宋書/卷88","薛安都、沈文秀、崔道固等北方州镇将领在泰始内战及宋魏转换中的经历；归降、招援与战果主要由南朝立场保存。"),
("v205_ss89","《宋书》卷八十九·袁粲等传","https://zh.wikisource.org/wiki/宋書/卷89","袁粲、褚渊在刘宋末年的中枢职位与不同选择；忠逆评价须与实际控制宫城、石头城和诏令的过程分开。"),
("v205_ss94","《宋书》卷九十四·恩幸传","https://zh.wikisource.org/wiki/宋書/卷94","戴法兴等近侍参与文书和宫廷政治的主要材料；篇名和传论带有门第官僚对近侍执政的贬抑。"),
("v205_nqs3","《南齐书》卷三·武帝纪","https://zh.wikisource.org/wiki/南齊書/卷3","齐武帝永明年间的任免、边防、灾害、赈济和政令编年；诏令不等于地方执行结果。"),
("v205_nqs4","《南齐书》卷四·郁林王纪","https://zh.wikisource.org/wiki/南齊書/卷4","萧昭业继位、萧鸾辅政及494年废杀的时序；私人挥霍与性格细节多服务于废立正当化。"),
("v205_nqs5","《南齐书》卷五·海陵王纪","https://zh.wikisource.org/wiki/南齊書/卷5","萧昭文被拥立、萧鸾录尚书事及数月后废黜的基本记录。"),
("v205_nqs6","《南齐书》卷六·明帝纪","https://zh.wikisource.org/wiki/南齊書/卷6","齐明帝即位、宗室处置、北魏进攻和建武政令的编年材料。"),
("v205_nqs7","《南齐书》卷七·东昏侯纪","https://zh.wikisource.org/wiki/南齊書/卷7","萧宝卷朝大臣清洗、陈显达与崔慧景起兵、寿阳易手及建康失守的时序。"),
("v205_nqs8","《南齐书》卷八·和帝纪","https://zh.wikisource.org/wiki/南齊書/卷8","江陵拥立、荆雍联军东下、郢城围攻、建康平定及齐梁禅代的基本编年。"),
("v205_nqs23","《南齐书》卷二十三·褚渊王俭传","https://zh.wikisource.org/wiki/南齊書/卷23","褚渊跨宋齐任职及王俭主持礼制、选举和国史的经历；齐朝对受禅合作者的评价需要逆读。"),
("v205_nqs26","《南齐书》卷二十六·王敬则陈显达传","https://zh.wikisource.org/wiki/南齊書/卷26","两位军功将领从宫禁、边战到晚年起兵的连续传记，也保存大量祥瑞和性格叙事。"),
("v205_nqs40","《南齐书》卷四十·武十七王传","https://zh.wikisource.org/wiki/南齊書/卷40","萧子良及齐武帝诸子的府学、政治位置和结局，是观察宗王文化网络与明帝清洗的重要材料。"),
]
sids={x[0] for x in sources}; d["sources"]=[x for x in d["sources"] if x["id"] not in sids]
d["sources"].extend({"id":i,"title":t,"url":u,"note":n} for i,t,u,n in sources)

P={
"ns_dai_faxing":("戴法兴","孝武朝近侍与文书官","长期处理孝武帝机要，前废帝亲政后被赐死；其权力来自宫廷信息通道而非正式宰相名位。",[
("寒门出身进入宫廷机要","戴法兴出身不显，早年以文书和办事能力进入刘宋宫廷，孝武帝即位后逐渐掌握诏令传达与人事信息。南朝官僚体系并非只有高门士族，皇帝也借近侍绕开外朝程序；但这种权力依赖个人信任，缺少公开职位边界。"),
("内外朝之间的信息门槛","官员奏事、诏令起草和皇帝接见都需要具体通道。戴法兴能够筛选信息、传达意旨，因而被外朝视为实权人物。把他只称作宠臣会遗漏制度机制；把所有政策归于他，也会过度放大近侍而减轻皇帝和正式尚书机构的责任。"),
("门第批评塑造了传记框架","《宋书》把戴法兴收入《恩幸传》，篇章分类本身就包含价值判断。高门作者常以出身、仪态和受宠解释近侍掌权，对其实际文书劳动记载较少。可核的是职务、赏赐、政令联系和死亡，嘲讽性逸闻不宜直接当人格全貌。"),
("顾命与亲政发生冲突","孝武帝去世后，戴法兴继续参与辅佐刘子业。少年皇帝逐渐把辅政理解为控制，戴法兴又缺少军队和独立官署保护。465年他被赐死，随后刘义恭、柳元景等顾命重臣也被清除，显示近侍与外朝并未形成可持续共同摄政。"),
("死亡罪状需要分层阅读","前废帝处死戴法兴时以专权等罪名解释亲政；后来的史书又把他写成能约束暴君的旧臣。两种叙述都受后续政局影响。较稳妥的结论是他曾深度参与机要，并在权力交接中失去信任，无法据单方罪状还原全部决策。"),
("他的经历揭示宫门政治","南朝最高决策不仅发生在尚书省，也发生在皇帝居所、内省和文书传递之间。戴法兴的上升与骤死说明，非正式信息权力可以很大，却很难制度化继承。理解他有助于解释两位废帝时期近侍、宿卫和宗室为何反复决定政局。"),]),
"ns_xue_andu":("薛安都","刘宋徐州将领","参加北伐和宗室内战，466年引北魏入彭城；个人求生最终改变南北边界。",[
("边镇将领跨越多次内战","薛安都出身河东，早年在北方作战，随刘骏讨刘劭，又参加454年平定刘义宣。其仕途来自前线军功而非稳定文官序列。徐州将领需要同时面对建康命令、北魏压力和本地军队生存，效忠选择往往伴随现实军事计算。"),
("义嘉战争中站到刘子勋一方","466年多州拥立刘子勋，薛安都以徐州兵拒绝明帝任命。寻阳政权败势形成后，他转而请降。把这种变化简单写成反复无常，会忽略两个宋廷并立、战局快速改变以及失败方将领缺少安全投降规则。"),
("请降与惧罪之间的致命误判","明帝接受归降，却派张永等率大军北上。薛安都担心朝廷借接收之机清算，于是请求北魏援助。魏军进入彭城后，宋魏接收安排转为军事对抗。个人安全、军队保全和中央威慑互相作用，制造双方都未必最初计划的升级。"),
("彭城易手牵动青徐诸镇","彭城是淮泗以北重要军政节点，易手后沈文秀、崔道固等青冀守将也在宋魏之间艰难选择。北魏军队最终扩大控制，刘宋失去多处北方州镇。边界变化不是一日完成，而是内战余波、围城和地方归附的连续结果。"),
("南北史书各有立场","南朝材料把招引北魏视为叛变，北魏材料则强调归附与接纳。薛安都确实主动求援，但具体承诺、兵数和会谈对白难以互证。分析责任时既不能抹去其选择，也不能把内战后的不安全归降环境从因果链中删除。"),
("州镇安全规则影响疆域","如果败方将领相信归降必受诛杀，就更可能向外部政权求援；中央若不带兵接收，又担心地方只是拖延。薛安都事件说明疆域并非只由国力比较决定，可信承诺、将领家属和部队安置也能改变城市归属。"),]),
"ns_yuan_can":("袁粲","刘宋末中枢重臣","幼主朝掌中枢，477年据石头城反对萧道成，计划泄露后战死。",[
("以高门文官进入顾命中枢","袁粲出身陈郡袁氏，历仕刘宋，明帝临终时进入辅政结构。幼主朝的尚书、诏令和名望需要这类高门官员维持，但正式尊位并不等于掌握宿卫。袁粲的处境体现文官中枢与军人宫禁权力逐渐分离。"),
("刘休范之乱后的权力倾斜","474年刘休范进攻建康，萧道成因守城获胜而掌握更多军队。袁粲等文官仍主持政务，却难以制衡实际控制宿卫的将领。朝廷表面维持共同辅政，内部资源已不对等；后废帝死亡只是让这种差距公开化。"),
("拥立顺帝不是完全同意新局面","477年刘昱被杀后，袁粲参与以皇太后名义拥立刘准，使行政名义得以延续。但接受紧急拥立不等于认可萧道成长期掌权。官员可能先避免宫廷真空，再对军权归属作出不同选择，不能把一次署名视为永久站队。"),
("石头城行动依赖内外响应","袁粲与刘秉等据石头城，联络宫内军官和外部将领，试图反制萧道成。计划泄露后，宫内同谋先被处置，石头城很快失守。高门声望和正统口号如果不能转化为稳定兵力，就难以对抗已经控制宫门的集团。"),
("忠臣记忆不能替代行动复盘","后世把袁粲视为宋室忠臣，齐朝史书也保留其临难形象。其抵抗事实明确，临终对白和完美从容则属于纪传塑造。更重要的是理解联络为何失败、哪些军官没有响应，以及首都不同据点如何决定政变成败。"),
("他的失败关闭中枢替代路径","袁粲败亡后，沈攸之的荆州军成为萧道成最后主要对手。石头城失败意味着建康内部已很难另组宋廷中枢。清洗还影响家属、府僚和基层军官，王朝更替因此是组织网络被拆解，而非只少一位忠臣。"),]),
"ns_chu_yuan":("褚渊","宋齐之际中枢官员","历仕宋明帝与幼主朝，选择协助萧道成完成受禅，成为宋齐转换的程序枢纽。",[
("婚姻与官职连接刘宋皇室","褚渊出身河南褚氏，尚宋文帝女南郡公主，兼有驸马和中枢官员身份。他参与选举、东宫和军务文书，义嘉战争时还奉命处理军中勋阶。其地位不是纯粹清谈名士，而建立在皇室亲属、行政经验和门第声望交汇处。"),
("北方失地前已参与边防判断","薛安都事件后，褚渊曾奉命慰劳北讨军，并就淮泗防务提出意见。传记保存的是奏议立场，不是完整战场调查，却说明文官也参与兵力、衣粮和城防安排。南朝军政并非武将独占，尚书中枢需要把前线信息转成调度。"),
("幼主朝在军权夹缝中任职","明帝死后，褚渊与袁粲等处在辅政核心。刘休范之乱提升萧道成军权，后废帝又与大臣关系恶化。褚渊选择与萧道成合作，并非说明他能自由控制局面；他的程序能力和名望却为掌军者提供了必要合法性。"),
("与袁粲走向不同道路","477年袁粲据石头城反对萧道成，褚渊没有加入，继续参与新中枢。后世常以忠奸对比二人。道德评价可以存在，但历史解释还需分析他们掌握的资源、对成功概率的判断，以及抵抗失败将给家族和官僚网络带来的风险。"),
("禅代程序需要他的合作","从齐公、九锡到齐王和受禅，每一步都要诏令、礼仪、官署和群臣署名。褚渊的作用是把萧道成已经取得的军事优势转译成旧朝可以发布的新秩序。程序并非虚假装饰，但它也不能证明顺帝拥有平等拒绝权。"),
("齐朝褒赞与宋遗民批评并存","《南齐书》肯定褚渊佐命，后世又以失节批评他。两种记忆都围绕改朝换代立场展开。理解褚渊，应同时保留其长期行政能力、实际合作行为和受禅的强制背景，避免把人物压缩成一个道德标签。"),]),
"ns_qi_wu":("萧赜","齐武帝","482—493年在位；永明朝以节用、户籍和边防维持稳定，也承受检籍冲突与北魏压力。",[
("继位建立在开国军政网络上","萧赜早年参与刘宋末年的军务和萧道成掌权，482年以成年太子继位，较少经历幼主摄政。褚渊、王俭等旧臣仍在中枢，王敬则、陈显达等军将分镇。永明稳定来自开国集团暂时合作，并非宫廷天然没有冲突。"),
("检籍是高帝遗政而非武帝新创","南齐清查户籍始于建元二年，目的在纠正冒籍、恢复赋役人口。执行中出现却籍，许多被判户籍不实者遭发配或追征。485年唐寓之起兵与此相关。到490年武帝调整旧案，说明改革并非一次完成，也不能把缓和写成彻底废止。"),
("永明政治重视账目与节用","本纪多次记录减省、赈贷、蠲租和约束地方，但宫廷、军镇和宗王府仍需持续支出。节俭诏令能显示政策语言，不能证明每个郡县都降低负担。观察成效还要看灾年粮价、逃户、征发及地方官是否利用检籍加码。"),
("边境在外交与攻防之间摆动","齐武帝时期与北魏既有使节往来，也有淮汉沿线攻防。州镇承担侦察、粮运、修城和安置流民，边境并非连续全面战争。地图上的疆界应理解为多层控制带，不是所有村落都在某日同时转换归属。"),
("竟陵王西邸连接宗室与知识","皇子萧子良在鸡笼山西邸聚集文士、僧人，形成文学和佛教讨论网络。王融、沈约、谢朓等人的活动后来被概括为竟陵八友，但名单和称谓来自后世整理。文化繁荣依赖王府资源，也受到宗室政治边界约束。"),
("继承安排留下旁支辅政风险","太子萧长懋先于武帝去世，皇太孙萧昭业继位。西昌侯萧鸾以宗室长辈和中枢职位进入辅政。成年皇帝顺利在位十一年，并未建立能保护孙辈免受辅政宗室废杀的制度，永明稳定因此很快中断。"),]),
"ns_qi_yulin":("萧昭业","郁林王","493—494年在位；皇太孙继位后与辅政宗室冲突，不足一年即被萧鸾废杀。",[
("皇太孙继承绕过早逝父亲","文惠太子萧长懋早逝后，武帝立长孙萧昭业为皇太孙。493年继位时，萧鸾任尚书令，竟陵王萧子良等宗室仍有声望。继承名义清楚，却没有规定新君与拥有军政资源的叔祖如何划分权力。"),
("即位诏令与实际控制并不相同","郁林王初即位曾颁布蠲免、减关市征赋和放还部分被掠人口等诏令。这些文本证明朝廷仍按常规运转，不能据此断言政策全面落实；也不能因其随后被废，就把短朝所有行政都视为毫无意义。"),
("挥霍叙述服务于废立合法性","《南齐书》集中描写萧昭业赏赐无度、私生活失检和欺骗长辈。部分财政支出可能有记录支持，夸张场景与对白则由废立后的明帝朝定型。可确认的是他与萧鸾关系恶化、亲近人员被利用为罪证，不能把整套猎奇叙述当现场档案。"),
("萧子良之死改变宗室平衡","竟陵王萧子良在武帝末和新君初具有太傅地位，旋即病逝。其王府文士网络无法转化为稳定军事力量。萧鸾由此成为最强宗室辅臣，宫城宿卫和诏令控制逐步集中，皇帝身边的亲信难以形成对等支持。"),
("494年废杀通过宫禁完成","萧鸾以皇太后令等形式废黜萧昭业，随后将其杀死。废立不是公开审判，而是先控制宫门、近侍和文书，再赋予行动名义。萧昭业被降为郁林王，称号本身也是胜利者重新安排正统记忆的一部分。"),
("短朝不应只剩荒淫标签","萧昭业应对自己的任用和支出负责，但其结局还源于皇太孙继承缺少强大亲军、辅政宗室掌握中枢，以及退位不保生命的传统。把失败全归于个人品行，会遮蔽南齐继承制度在开国后十二年即失灵。"),]),
"ns_qi_hailing":("萧昭文","海陵王","494年在位数月；由萧鸾拥立为过渡皇帝，军政与任免均受辅政者控制。",[
("被拥立时只有十四岁","萧昭文是文惠太子次子，兄长萧昭业被废后由萧鸾议立。年轻、缺少独立军府和亲信，使他适合作为政权连续的名义中心。拥立维持高帝直系仍在位的表象，也给萧鸾进一步清理宗室和安排官职提供时间。"),
("延兴朝只有数月却有完整仪式","萧昭文即位、改元延兴、大赦并任命百官，说明皇帝名号仍是行政文书的必要中心。与此同时，萧鸾以录尚书事、扬州刺史等职位掌握中枢和首都。形式运转与实权旁落可以同时为真。"),
("巡行与赈令不能证明自主决策","本纪记录遣使巡行、赈恤和人员任命，但无法逐项证明由萧昭文本人决定。幼主名下诏令往往来自掌权集团。可靠写法应区分谁署名、谁起草、谁控制执行，而不是把所有政令都算作皇帝个人政绩。"),
("高武诸子被逐步隔离","萧鸾在辅政期间调动、控制乃至杀害高帝和武帝后裔，消除可能借宗王府兵反对废立的人选。海陵王身处同一家族清洗之中，即使没有主动挑战，也因直系血统成为需要被替换的政治符号。"),
("废位后很快死亡","494年十月，萧鸾废萧昭文为海陵王，自立为帝；不久萧昭文被杀，年仅十五。官方可用疾病或礼制语言淡化过程，其他材料指向强制处置。可确定的是退位没有带来长期安全，死亡紧随权力移交。"),
("过渡皇帝揭示名位的工具性","海陵王不是帝序中可跳过的空白。他的数月在位说明掌权者仍需借高武直系名义完成官员重组，待反对力量削弱后才改由旁支称帝。理解这段过渡，才能看清萧鸾夺位是分阶段实施，而非单日宣布。"),]),
"ns_qi_ming":("萧鸾","齐明帝","494—498年在位；通过连续废立取得帝位，清除高武后裔，并在北魏南攻中重组边防。",[
("辅政权逐步变成皇权","萧鸾是高帝侄、始安贞王之子，以西昌侯身份在武帝末进入中枢。郁林王朝任尚书令后，他先废杀萧昭业，再拥立萧昭文，数月后自立。连续步骤显示夺位依赖宫禁、尚书和宗室名分逐层转换。"),
("宗室清洗具有预防性逻辑","萧鸾大量处置高帝、武帝子孙，原因不只个人仇恨：这些宗王拥有血统名望、地方职位和潜在府兵。预防性杀戮短期减少竞争者，却进一步摧毁宗室之间的安全承诺，使幸存者和州镇将领更倾向先发反抗。"),
("建武北战暴露边境压力","北魏在建武年间进攻司、豫、徐、梁等州，钟离、义阳及淮汉城镇承受攻防。齐廷调陈显达等将领出战，也修城、运粮和安置人口。胜败不能只看单场战报；边民的耕作、迁徙和征役构成长期成本。"),
("农桑诏令与战争财政并存","本纪反复要求州郡劝课农桑、修堤防、审理刑狱，也有灾害赈济和减免。与此同时，北战、宫廷宿卫和宗室清洗需要资源。诏令展现治理目标，实际效果须与逃亡、粮运和地方执行比较，不能自动推出建武中兴。"),
("军功旧臣也失去安全感","王敬则、陈显达等开国将领拥有资历和部众，面对明帝持续清洗而日益不安。王敬则于498年起兵，迅速失败；这不证明所有恐惧都合理，却说明政权已难提供可信的退休和降职安排。"),
("把不稳定留给下一代","498年明帝死，子萧宝卷继位。明帝为儿子清除大量宗室，却仍需依赖萧遥光、陈显达等军政大臣。可用亲族减少、功臣缺乏安全、边防压力未解，使新君一旦继续清洗，朝廷便迅速滑向多次起兵。"),]),
"ns_qi_donghun":("萧宝卷","东昏侯","498—501年在位；连续清洗大臣和州镇失控引发多次起兵，最终在建康被杀。",[
("继位承接的是高度紧张的朝廷","萧宝卷十八岁继位，明帝已大量杀害高武宗室，留下的军政重臣彼此缺乏信任。新君并非面对一个稳定官僚机器，而是面对掌兵功臣、旁支宗王和宫内近侍交错的网络；他的清洗进一步放大原有不安全。"),
("猎奇宫廷叙事必须分层","《南齐书》详细描写潘妃、宫苑、出游和暴行，后世据此形成东昏侯形象。宫殿工程、赏赐和多位大臣被杀可以核对，金莲、街市等戏剧化细节则带有梁朝胜利者塑造亡国之君的功能，不宜全部当作即时记录。"),
("重臣接连被杀破坏决策能力","萧宝卷先后杀害萧遥光、徐孝嗣、沈文季、萧懿等人或迫使其集团反抗。每次清洗都可能解除眼前威胁，却让尚书、宿卫和边镇失去经验人员，也向其余将领证明服从未必换来安全。"),
("寿阳易手是内政外溢","豫州刺史裴叔业担心被诛，于500年以寿阳降北魏。南齐随后出兵争夺失败，重要边镇转入北魏控制。与薛安都事件相似，个人求生、中央猜疑和外部政权接纳共同改变疆界，不能只归为一名守将叛变。"),
("陈显达与崔慧景先后逼近建康","499年陈显达从寻阳起兵，500年崔慧景又从广陵进攻并一度进入建康。两次行动均失败，却显示首都防务、外镇军心和皇帝威望持续恶化。平叛成功没有恢复信任，反而带来新一轮任免和杀戮。"),
("萧衍联军结束其统治","萧懿被杀后，其弟萧衍在襄阳起兵，与江陵方面拥立的萧宝融政权合作，沿江东下。501年建康失守，萧宝卷被近臣杀死并追废为东昏侯。结局由州镇战争和宫内倒戈共同造成，不是单一民怨自动推翻。"),]),
"ns_qi_he":("萧宝融","齐和帝","501—502年在位；在江陵被拥立为对抗萧宝卷的皇帝，建康平定后禅位于萧衍。",[
("江陵拥立形成第二个齐廷","萧宝融是明帝第八子，时任荆州刺史。萧衍起兵后，江陵集团于501年拥立他为帝、改元中兴。南齐再次出现两个皇帝名号；江陵政权拥有荆雍资源和官署，不应只称为一支地方叛军。"),
("萧颖胄与萧衍分掌上游联盟","江陵中枢由萧颖胄等主持，萧衍统率东征主力。联盟内部并非从一开始就完全一致，军令、补给和未来权力都需协调。萧颖胄去世后，萧衍对军政和建康接收的控制进一步增强。"),
("郢城围攻决定东下速度","东征军在郢城等长江节点经历长期攻守，水军、粮船和沿岸降附决定能否继续推进。和帝诏令提供名义，真正让州镇转向的是战局与后勤。把战争写成萧衍一路凯歌，会遗漏围城饥饿、民夫征发和反复归降。"),
("建康平定后皇帝仍在江陵","501年底建康失守，萧宝卷已死，但萧宝融并未立即亲临首都。萧衍以梁王和大司马身份在建康掌百官、军队和财政。名义皇帝与实际中枢分处两地，清楚显示权力转换早于正式禅位。"),
("502年禅让延续南朝程序","和帝下诏禅位，萧衍建立梁朝。齐梁转换同样经过封公、进王、授九锡等步骤，把军事胜利翻译为礼制秩序。程序真实存在，但幼主没有对等军队和拒绝条件，因此不能以文书形式证明完全自愿。"),
("退位后生命仍无保障","萧宝融退位后被封巴陵王，随后被杀，年十五。齐朝本身通过宋顺帝受禅建立，二十三年后又以相似方式结束；两位少年退位者都未获长期安全。重复模式说明礼遇承诺不足以约束新王朝的风险判断。"),]),
"ns_wang_jian_qi":("王俭","南齐礼制与选举重臣","协助萧道成受禅并主持南齐礼制、国史和人才选举，是开国行政秩序的重要组织者。",[
("高门家学与刘宋仕历","王俭出身琅邪王氏，早年历仕刘宋，熟悉礼学、文书和选举。门第给他进入中枢的资格，却不能自动产生政策；其实际价值在于能把经学、官制和仪式转成可执行文本，连接旧朝人员与新朝制度。"),
("受禅中的程序设计","萧道成掌权后，王俭参与封国、礼仪和禅代文书。军队控制决定谁有能力夺位，礼制程序则决定官员如何转移职名、朝会和法统。参与程序意味着支持改朝换代，但不能把程序简单视作无意义包装。"),
("齐初官制需要连续而非重造","南齐沿用大量刘宋尚书、州郡和品秩体系，王俭等人负责调整名号、礼仪和人员。新朝不会一夜更换所有县吏与税册，制度连续有助于维持行政，也让前朝形成的门第差等和征发问题继续存在。"),
("选举权连接知识与仕途","王俭掌选举时重视文学和礼学人才，许多后来的南朝文士进入视野。选举既评价才能，也受门第、推荐和政治可靠性影响。所谓唯才是举不能脱离名籍、家世与中枢网络，文化繁荣也有明确制度门槛。"),
("国史编纂塑造开国记忆","王俭参与国史和礼书编纂，决定哪些诏令、功臣和仪式进入官方记录。齐朝材料强调萧道成受命和平乱功绩，对袁粲、沈攸之等反对者另有定性。史官保存事实线索，也在新政权框架内组织褒贬。"),
("早逝使开国平衡失去一环","王俭在齐武帝初年去世，年仅三十八。其后永明朝仍保持一段稳定，但开国文官、军将与宗室的平衡逐渐变化。理解王俭，不只看个人才名，还要看礼制专家如何让军事胜利转为可持续行政。"),]),
"ns_xiao_ziliang":("萧子良","竟陵文宣王","齐武帝次子，西邸聚集文士僧人并参与赈济议政；其文化网络未能转化为继承军力。",[
("成年宗王参与永明政务","萧子良是齐武帝之子，历任司徒等高职，不只是文学赞助者。他以宗王身份参与议政、赈济和官员交往，王府能够汇集文书、宾客和资源。宗王文化活动与国家行政相连，不能被隔离成纯粹雅集。"),
("西邸是持续性知识网络","鸡笼山西邸聚集王融、沈约、谢朓、萧衍等文士，也与僧人讨论佛教义理。后来“竟陵八友”称谓便于记忆，却可能简化实际参与者和时间差异。更准确的是一个由王府资源维系、人员流动的知识网络。"),
("佛教实践包含组织和救济","萧子良支持讲经、斋会和佛教著述，也关注灾民与施舍。宗教活动既有信仰和思想层面，也需要粮食、场所、抄写与人员。赞助能扩大知识传播，同时体现宗王拥有普通编户难以企及的资源。"),
("文学新声与政治机会并存","永明文学重视声律和精炼表达，西邸文士后来分散到齐梁中枢。文学风格不是由一次聚会突然发明，而在官场唱和、佛经音韵和家学写作中逐渐形成。王府提供机会，也使文士与宗室命运发生联系。"),
("武帝末年的继承想象","文惠太子去世、武帝病重时，萧子良作为成年皇子拥有声望，王融等人可能设想由其承担更大角色。现存材料对具体拥立谋划带有事后追责色彩。可确认的是他未掌握足以改变继承的军队，皇太孙萧昭业仍即位。"),
("文化声望没有抵挡辅政夺权","萧子良在郁林王初年任太傅，旋即病逝。其宾客网络没有形成独立军府，萧鸾随后控制中枢。这个结局说明南朝宗王的文学、宗教和名望可以影响文化，却不能自动转化为宫门、宿卫和州镇控制。"),]),
}

