events=[
("p01","465年","戴法兴被赐死与顾命崩解","前废帝先处死戴法兴，继而清除刘义恭、柳元景等辅政者。","亲政缺少制度边界，近侍和外朝顾命都无法获得稳定授权。",["ns_dai_faxing","ns_song_qianfei"],["v205_ss94"]),
("p02","466—467年","薛安都请降、招魏与彭城易手","义嘉政权失败后薛安都请降，因担心清算又引北魏军进入彭城。","归降安全失信把内战余波转化为南北边界变化。",["ns_xue_andu","ns_song_ming"],["v205_ss88","v205_nqs23"]),
("p03","477年","袁粲石头城行动","袁粲、刘秉等联络宫内外军官，试图反制萧道成，计划泄露后败亡。","文官正统声望若无稳定军力，难以对抗掌握宿卫的集团。",["ns_yuan_can","ns_chu_yuan","ns_qi_gao"],["v205_ss89","v205_nqs23"]),
("p04","479年","褚渊、王俭与宋齐受禅程序","褚渊、王俭等参与封齐公、九锡、进王及受禅文书。","行政程序使官员和州郡逐级转入新朝，但不证明退位者拥有对等选择。",["ns_chu_yuan","ns_wang_jian_qi","ns_qi_gao"],["v205_nqs23"]),
("p05","493—494年","皇太孙继位与连续废立","萧昭业继位后与萧鸾冲突，萧鸾先废杀昭业、拥立昭文，继而再次废位自立。","继承名义未能约束掌握宫禁和尚书的辅政宗室。",["ns_qi_yulin","ns_qi_hailing","ns_qi_ming"],["v205_nqs4","v205_nqs5","v205_nqs6"]),
("p06","501—502年","江陵拥立与齐梁禅代","江陵拥立萧宝融，萧衍联军攻入建康；次年和帝禅位，梁朝建立。","两个齐廷的战争先完成实际权力转移，禅让礼仪随后确认结果。",["ns_qi_donghun","ns_qi_he","ns_liang_wu"],["v205_nqs7","v205_nqs8"]),
("m01","466—469年","彭城、青州与冀州的连续失守","北魏介入彭城后，青冀州镇经历围攻、归降和控制转换。","州镇易手是数年过程，居民随之面对兵役、迁徙和户籍重编。",["ns_xue_andu","ns_song_ming"],["v205_ss88"]),
("m02","484—493年","永明边境攻防与使节往来","齐魏在淮汉州镇交替出现攻防、警戒与遣使。","边境不是持续全面战争，粮运、修城和局部控制比单线疆界更复杂。",["ns_qi_wu"],["v205_nqs3"]),
("m03","495—497年","建武北魏南攻","北魏进攻司、豫、徐、梁等州，齐军围绕钟离、义阳等节点防守反击。","前线居民承担运输、筑城和流离成本，战报无法提供完整伤亡。",["ns_qi_ming"],["v205_nqs6","v205_nqs26"]),
("m04","498年","王敬则起兵","开国宿将王敬则因担心清洗自会稽起兵，向建康推进后迅速失败。","功臣缺少安全退场，使预防性反抗与中央猜疑互相强化。",["ns_qi_ming"],["v205_nqs6","v205_nqs26"]),
("m05","499—500年","陈显达与崔慧景先后进逼建康","陈显达、崔慧景分别从外镇起兵，后者一度进入建康，均告失败。","重复平叛没有恢复信任，反而持续损耗军政骨干。",["ns_qi_donghun"],["v205_nqs7","v205_nqs26"]),
("m06","500—501年","寿阳易手与荆雍联军东下","裴叔业以寿阳降魏；萧衍随后从襄阳起兵，经历郢城战线后攻入建康。","边镇求生和首都清洗同时改变北部边界与王朝归属。",["ns_qi_donghun","ns_qi_he","ns_liang_wu"],["v205_nqs7","v205_nqs8"]),
("c01","479年前后","受禅礼制与新朝国史","王俭等组织齐公、九锡和受禅程序，并参与新朝史礼编纂。","礼制既维持行政连续，也以胜利王朝框架重排人物褒贬。",["ns_chu_yuan","ns_wang_jian_qi","ns_qi_gao"],["v205_nqs23"]),
("c02","482—493年","竟陵西邸的文学与佛教网络","萧子良王府汇集文士和僧人，开展写作、讲经与交往。","文化创新依赖王府资源和流动网络，不是固定八人一次聚会的产物。",["ns_xiao_ziliang","ns_qi_wu"],["v205_nqs3","v205_nqs40"]),
("c03","482—493年","声律探索与官场写作","沈约、谢朓等在王府和官场写作中推进声律意识。","永明体是长期实践和后世归纳，不能归于单一发明者或确切一日。",["ns_xiao_ziliang"],["v205_nqs40"]),
("c04","494年以后","废帝称号与亡国之君叙事","萧昭业、萧昭文被降封，萧宝卷后来被称东昏侯。","称号和猎奇传记由胜者固定，行动事实与道德修辞必须分层。",["ns_qi_yulin","ns_qi_hailing","ns_qi_donghun"],["v205_nqs4","v205_nqs5","v205_nqs7"]),
("c05","494—498年","宗室谱系与合法性重排","萧鸾恢复部分被杀宗王属籍，同时以自身旁支重组继承。","属籍、封爵和祭祀决定谁被承认为皇族，并非单纯家谱记录。",["ns_qi_ming"],["v205_nqs6"]),
("c06","501—502年","中兴年号与梁王礼制升级","江陵齐廷使用中兴年号，萧衍在建康逐级受封梁公、梁王。","两套政治中心通过年号和礼仪争取官员承认，实际军权仍是基础。",["ns_qi_he","ns_liang_wu"],["v205_nqs8"]),
("e01","480—485年","检籍、却籍与唐寓之起兵","南齐清查冒籍恢复赋役，执行中大量却籍，唐寓之在三吴起兵。","财政整顿进入户籍和家庭身份，错误或苛急执行会造成广泛社会冲突。",["ns_qi_gao","ns_qi_wu"],["v205_nqs3"]),
("e02","490年","永明八年调整却籍","武帝允许部分宋升明以前旧籍恢复，部分谪戍者还乡，并限制继续冒籍。","调整承认积案与民怨，但没有取消国家核定赋役人口的目标。",["ns_qi_wu"],["v205_nqs3"]),
("e03","482—493年","灾害赈济、蠲租与粮种贷给","永明本纪多次记录水旱后赈恤、减租和贷种。","重复救济说明江南财赋区仍脆弱，诏令也不能证明每户实际获给。",["ns_qi_wu"],["v205_nqs3"]),
("e04","493—494年","短朝蠲免与宫廷支出争议","郁林王初免逋调和部分债务，史书同时指控赏赐和宫廷支出过度。","财政措施与废立罪状需分别核对，不能用亡国叙事抹去全部政令。",["ns_qi_yulin"],["v205_nqs4"]),
("e05","495—500年","北战军粮与边镇财政","建武北战及寿阳危机持续征调粮船、兵器与民夫。","军费从中央预算传到州县征发，也压缩灾害救济和家庭生产。",["ns_qi_ming","ns_qi_donghun"],["v205_nqs6","v205_nqs7"]),
("e06","501—502年","东征军需与建康接收","荆雍联军沿江东进，需要郢城粮道、降附州郡和建康府库支持。","改朝换代同时是军粮、官俸和税源的接管过程。",["ns_qi_he","ns_liang_wu"],["v205_nqs8"]),
("s01","465年","近侍与顾命家族的连带清洗","戴法兴及多位顾命大臣被杀，亲属和门生网络亦受冲击。","宫廷清洗改变的不只是官位，也包括家庭安全与信息通道。",["ns_dai_faxing","ns_song_qianfei"],["v205_ss94"]),
("s02","466—469年","淮泗居民面对政权转换","彭城、青州等地在宋魏军队、围城和归降之间转换控制。","居民需要重新应对军役、户籍和迁徙，疆界变化不是地图瞬间换色。",["ns_xue_andu"],["v205_ss88"]),
("s03","480年代","却籍者的身份、发配与反抗","被判冒籍者可能失去原有户籍待遇、遭追征或发配，三吴社会因此动荡。","国家校验名册会直接改变家庭身份，不能只当技术性行政改革。",["ns_qi_wu"],["v205_nqs3"]),
("s04","482—493年","宗王府、僧侣与文士的城市生活","西邸讲经、宴集和写作依赖建康空间、抄写劳动与王府供给。","文化活动背后有僧俗劳动和资源差等，不只是名士名单。",["ns_xiao_ziliang","ns_qi_wu"],["v205_nqs40"]),
("s05","494—498年","高武后裔家族被系统清除","萧鸾处置多位宗王及其家属、府僚，重组皇族属籍。","预防性政治把血统本身变成风险，削弱王朝可依赖的亲族网络。",["ns_qi_ming","ns_qi_hailing"],["v205_nqs5","v205_nqs6","v205_nqs40"]),
("s06","500—502年","围城、降附与普通军民选择","寿阳、郢城和建康战事迫使军户、民夫、居民在守城、逃亡和投降之间选择。","齐梁转换的社会代价远超帝序中的两次禅位。",["ns_qi_donghun","ns_qi_he","ns_liang_wu"],["v205_nqs7","v205_nqs8"]),
]
